        public static void SetArrowCount(Entity boss, int value) => boss.SetBehaviourField(PROP_ARROW_COUNT, value);
        #endregion 属性

        private static float GetChangeAdjacentLaneZSpeed(Entity boss)
        {
            var dir = 0;
            var lane = boss.GetLane();
            var maxLane = boss.Level.GetMaxLaneCount();
            if (lane <= 0)
            {
                dir = 1;
            }
            else if (lane >= maxLane - 1)
            {
                dir = -1;
            }
            else
            {
                dir = boss.RNG.Next(2) * 2 - 1;
            }
            var targetLane = Mathf.Clamp(lane + dir, 0, maxLane - 1);
            return GetChangeLaneZSpeed(boss, targetLane);
        }
        private static float GetChangeLaneZSpeed(Entity boss, int targetLane)
        {
            var targetZ = boss.Level.GetEntityLaneZ(targetLane);
            return GetChangeZSpeed(boss, targetZ);
        }
        private static float GetChangeZSpeed(Entity boss, float targetZ)
        {
            var currentZ = boss.Position.z;
            return (targetZ - currentZ) / 16.6f;
        }
        public static bool CanUseFabric(Entity boss)
        {
            var count = GetFabricCount(boss);
            if (count >= MAX_FABRIC_COUNT)
                return false;
            var timer = GetFabricCooldownTimer(boss);
            if (timer == null || !timer.Expired)
                return false;
            return true;
        }
        public static void UseFabric(Entity boss)
        {
            stateMachine.StartState(boss, STATE_FABRIC);
            SetFabricCount(boss, GetFabricCount(boss) + 1);
            var timer = GetFabricCooldownTimer(boss);
            timer?.Reset();
            SetRecentTakenDamage(boss, 0);
            boss.PlaySound(VanillaSoundID.nimbleFabric);
        }
        public static bool ShouldCamera(Entity boss)
        {
            return cameraDetector.DetectEntityCount(boss) >= CAMERA_ENEMY_COUNT;
        }
        public static bool ShouldGapBomb(Entity boss)
        {
            var column = boss.GetMirroredColumn(0, true);
            if (boss.IsAheadOfColumn(column))
                return false;
            return gapBombDetector.DetectEntityCount(boss) >= GAP_BOMB_ENEMY_COUNT;
        }
        public static bool ShouldFrontFlip(Entity boss)
        {
            return boss.IsBehindOfColumn(boss.Level.GetMaxColumnCount() / 2);
        }
        public static bool ShouldBackflip(Entity boss)
        {
            return boss.IsAheadOfOrAtColumn(boss.Level.GetMaxColumnCount() / 2);
        }
        public static bool CanFrontflip(Entity boss)
        {
            var column = boss.GetMirroredColumn(1, false);
            return boss.IsBehindOfColumn(column);
        }
        public static bool CanBackflip(Entity boss)
        {
            var column = boss.GetMirroredColumn(1, true);
            return boss.IsAheadOfColumn(column);
        }
        public static Entity? FindHammerTarget(Entity boss)
        {
            return hammerCheckDetector.DetectEntityWithTheLeast(boss, e => Mathf.Abs(e.Position.x - boss.Position.x));
        }

        //EXPAND ===== 子弹收获类技能（箭雨/夺取子弹）=====
        //收集场上所有对正邪敌对的弹射物（即器械方发射的子弹）。
        public static void FindHostileProjectiles(Entity boss, List<Entity> results)
        {
            results.Clear();
            foreach (var e in boss.Level.FindEntities(e => e.Type == EntityTypes.PROJECTILE && e.IsHostile(boss)))
            {
                results.Add(e);
            }
        }
        //场上敌对子弹足够多时才施放。
        public static bool ShouldHarvestProjectiles(Entity boss)
        {
            arrowRainBuffer.Clear();
            FindHostileProjectiles(boss, arrowRainBuffer);
            return arrowRainBuffer.Count >= BULLET_HARVEST_COUNT;
        }

        //EXPAND ===== 技能：召唤反则卫星 =====
        //场上没有反则卫星时才召唤（卫星死亡后可再次召唤）。
        public static bool ShouldReverseSatellite(Entity boss)
        {
            return !boss.Level.EntityExists(VanillaEnemyID.reverseSatellite);
        }
        /// <summary>
        /// 颠倒玩家的机械能数值（契合正邪的“反转”之力）：
        /// 先把数值转为字符串，倒序排列后再把 6 和 9 互换（其余数字颠倒后视为本身），
        /// 最后转换回数值。若颠倒后的数值小于当前数值（对玩家的减益），则替换玩家机械能；否则保持不变（增益不生效）。
        /// 例：1225 -> 5221（高于原值，不生效）；601 -> 109（低于原值，机械能变为 109）。
        /// </summary>
        public static void ReverseLevelEnergy(LevelEngine level)
        {
            var current = (long)level.Energy;
            var text = current.ToString();
            var sb = new StringBuilder(text.Length);
            for (int i = text.Length - 1; i >= 0; i--)
            {
                var c = text[i];
                //6 和 9 在颠倒时互换：6 颠倒过来是 9，9 颠倒过来是 6。
                if (c == '6')
                    c = '9';
                else if (c == '9')
                    c = '6';
                sb.Append(c);
            }
            if (long.TryParse(sb.ToString(), out var reversed))
            {
                //只有颠倒后的数值小于当前数值（减益）时才替换。
                if (reversed < current)
                {
                    level.SetEnergy(reversed);
                }
            }
        }

        //EXPAND ===== 技能：魅惑器械 =====
        //场上还有玩家阵营的器械时才可施放。
        public static bool ShouldCharmContraptions(Entity boss)
        {
            charmBuffer.Clear();
            FindCharmTargets(boss, charmBuffer);
            return charmBuffer.Count > 0;
        }
        //随机挑选至多 CHARM_TARGET_COUNT 个玩家阵营的器械。
        public static void FindCharmTargets(Entity boss, List<Entity> results)
        {
            var level = boss.Level;
            //器械为 PLANT 类型；排除已被魅惑（非敌对）与不可被选取的器械。
            var all = level.FindEntities(e => e.Type == EntityTypes.PLANT && e.IsHostile(boss) && e.IsVulnerableEntity());
            //打乱数组后取前 N 个，保证随机。
            for (int i = all.Length - 1; i > 0; i--)
            {
                int j = boss.RNG.Next(i + 1);
                var temp = all[i];
                all[i] = all[j];
                all[j] = temp;
            }
            var count = Mathf.Min(CHARM_TARGET_COUNT, all.Length);
            for (int i = 0; i < count; i++)
            {
                results.Add(all[i]);
            }
        }

